using json=nlohmann::ordered_json;using Tokens=std::vector<llama_token>;using Floats=std::vector<float>;using Bytes=std::vector<uint8_t>;
static void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
static std::string sha(const void*p,size_t n){unsigned char d[32];unsigned l;need(EVP_Digest(p,n,d,&l,EVP_sha256(),nullptr)==1,"digest");std::ostringstream o;for(unsigned i=0;i<l;++i)o<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(d[i]);return o.str();}
template<class T>static std::string sha(const std::vector<T>&v){return sha(v.data(),v.size()*sizeof(T));}
static Bytes state(llama_context*c,bool full=false){llama_synchronize(c);Bytes v(full?llama_state_get_size(c):llama_state_seq_get_size(c,0));need((full?llama_state_get_data(c,v.data(),v.size()):llama_state_seq_get_data(c,v.data(),v.size(),0))==v.size(),"save");return v;}
static void restore(llama_context*c,const Bytes&v){need(llama_state_seq_set_data(c,v.data(),v.size(),0)==v.size(),"restore");}
static Tokens part(const Tokens&t,int p,int n){return{t.begin()+p,t.begin()+p+n};}
static Floats logits(llama_context*c,int n=1){int nv=llama_vocab_n_tokens(llama_model_get_vocab(llama_get_model(c)));Floats v;for(int i=0;i<n;++i){auto*q=llama_get_logits_ith(c,n==1?-1:i);need(q,"logits");for(int j=0;j<nv;++j)need(std::isfinite(q[j]),"nonfinite");v.insert(v.end(),q,q+nv);}return v;}
static Floats apply(llama_context*t,llama_context*d,common_speculative*s,const Tokens&ids,int pos,bool all=false,bool out=true){auto b=llama_batch_init(ids.size(),0,1);b.n_tokens=ids.size();for(int i=0;i<b.n_tokens;++i){b.token[i]=ids[i];b.pos[i]=pos+i;b.n_seq_id[i]=1;b.seq_id[i][0]=0;b.logits[i]=all||(out&&i==b.n_tokens-1);}need(llama_decode(t,b)==0,"target decode");Floats v;if(out)v=logits(t,all?ids.size():1);need(common_speculative_process(s,b),"feature process");llama_synchronize(d);llama_batch_free(b);return v;}
static json draft(common_speculative*s,llama_context*d,Tokens&prompt,int pos,int anchor,int k){Tokens ids;Floats conf;auto&p=common_speculative_get_draft_params(s,0);p.drafting=true;p.n_max=k;p.n_past=pos;p.id_last=anchor;p.prompt=&prompt;p.result=&ids;p.confidence=&conf;common_speculative_draft(s);need(ids.size()==size_t(k)&&conf.size()==size_t(k),"draft width");auto v=logits(d,k);return{{"ids",ids},{"confidence",conf},{"logits",sha(v)},{"seq",sha(state(d))},{"global",sha(state(d,true))}};}
int main(int argc,char**argv){json out={{"complete",false},{"cases",json::array()}};std::filesystem::path dest=argv[1];std::filesystem::create_directories(dest);auto save=[&]{std::ofstream(dest/"results.json")<<out.dump(2)<<'\n';};try{std::ifstream f(argv[2]);auto input=json::parse(f);common_init();common_params p;std::vector<char*>args{argv[0]};for(int i=3;i<argc;++i)args.push_back(argv[i]);need(common_params_parse(args.size(),args.data(),p,LLAMA_EXAMPLE_SERVER),"params");p.fit_params=false;p.warmup=false;p.n_outputs_max=p.n_outputs_max_per_seq=6;p.speculative.draft.backend_sampling=false;p.speculative.draft.p_min=0;p.speculative.draft.n_max=5;setenv("LLAMA_DSPARK_CUM_P_MIN","0",1);setenv("LLAMA_DSPARK_EMPTY_COOLDOWN","0",1);unsetenv("LLAMA_DSPARK_GPU_FEATURES");unsetenv("LLAMA_DSPARK_GPU_FEATURES_LOCAL");unsetenv("LLAMA_DSPARK_GPU_FEATURES_ASYNC");unsetenv("LLAMA_DSV41_PREFILL_SKIP");llama_backend_init();auto init=common_init_from_params(p);auto*t=init->context();need(t,"target");common_threadpools tp;tp.init(t,p);auto pd=common_base_params_to_speculative(p);auto di=common_speculative_init_from_params(pd,init->model(),t);auto*d=di->context();need(d,"draft");common_threadpools dp;dp.init(d,pd);p.speculative.draft.ctx_tgt=t;p.speculative.draft.ctx_dft=d;common_speculative_ptr spec(common_speculative_init(p.speculative,1));need(bool(spec),"spec");need(llama_set_dflash_prefill_tail(t,d),"tail registration");std::cerr<<"READY\n";int nv=llama_vocab_n_tokens(llama_model_get_vocab(llama_get_model(t)));
for(auto&corpus:input["cases"]){std::string id=corpus["id"];auto tok=corpus["tokens"].get<Tokens>();for(int n:{8192,7681}){json ref;for(int mode:{0,1,2}){if(mode==0)unsetenv("LLAMA_DSV41_PREFILL_SKIP");else setenv("LLAMA_DSV41_PREFILL_SKIP",mode==1?"1":"0",1);llama_memory_clear(llama_get_memory(t),true);llama_memory_clear(llama_get_memory(d),true);common_speculative_set_state(spec.get(),0,{});std::cerr<<"PREFIX "<<id<<' '<<n<<' '<<mode<<'\n';auto v=apply(t,d,spec.get(),part(tok,0,n),0);uint32_t begin=0,end=0;need(llama_get_embeddings_layer_inp_range(t,&begin,&end)&&end==unsigned(n),"range");if(mode==1){need(begin==unsigned((n-768)/512*512),"suffix begin");need(!llama_get_embeddings_layer_inp_packed(t,begin-1,1),"invalid packed row");need(!t->get_layer_input_span(39,begin-1,1),"invalid host row");need(!llama_get_embeddings_layer_inp(t,39),"full getter accepted partial");}else need(begin==0,"full begin");
json row={{"target_logits",sha(v)},{"target_seq",sha(state(t))},{"target_global",sha(state(t,true))},{"draft_seq",sha(state(d))},{"draft_global",sha(state(d,true))},{"taps",json::array()}};unsigned tail=(n-768)/512*512;for(int lid:{37,38,39}){float*q=t->get_layer_input_span(lid,tail,n-tail);need(q,"valid span");row["taps"].push_back(sha(q,size_t(n-tail)*llama_model_n_embd(llama_get_model(t))*sizeof(float)));}auto st=state(t),sd=state(d);int anchor=std::max_element(v.end()-nv,v.end())-(v.end()-nv);Tokens prompt=part(tok,0,n);common_speculative_begin(spec.get(),0,prompt);row["K3"]=draft(spec.get(),d,prompt,n,anchor,3);restore(d,sd);row["K5"]=draft(spec.get(),d,prompt,n,anchor,5);restore(d,sd);restore(t,st);need(!llama_get_embeddings_layer_inp_range(t,&begin,&end),"restore stale range");need(!llama_get_embeddings_layer_inp_packed(t,0,1),"packed after restore");need(!t->get_layer_input_span(39,0,1),"span after restore");llama_token one=1;llama_batch bad={};bad.token=&one;std::cerr<<"NEGATIVE_BEGIN\n";need(llama_decode(t,bad)==-1,"empty decode");need(!llama_get_embeddings_layer_inp_range(t,&begin,&end)&&!llama_get_embeddings_layer_inp_packed(t,0,1),"packed after failed decode");need(sha(state(t))==sha(st),"bad decode changed KV");std::cerr<<"NEGATIVE_END\n";need(llama_set_dflash_prefill_tail(t,d)&&!llama_get_embeddings_layer_inp_packed(t,0,1),"packed after mode change");auto follow=apply(t,d,spec.get(),part(tok,n,6),n,true);row["verify_logits"]=sha(follow);row["verify_target"]=sha(state(t));row["verify_draft"]=sha(state(d));need(llama_get_embeddings_layer_inp_range(t,&begin,&end)&&begin==0&&end==6,"fresh range");need(llama_get_embeddings_layer_inp_packed(t,0,1)!=nullptr,"fresh packed");
if(mode==0)ref=row;else if(row!=ref){out["mismatch"]={{"corpus",id},{"n",n},{"mode",mode},{"reference",ref},{"actual",row}};save();throw std::runtime_error("mode mismatch");}out["cases"].push_back({{"corpus",id},{"n",n},{"mode",mode},{"result",row}});save();std::cerr<<"EXACT "<<id<<' '<<n<<' '<<mode<<'\n';}}}out["complete"]=true;save();std::cerr<<"JOINT_DONE\n";return 0;}catch(const std::exception&e){out["error"]=e.what();save();std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
